import { expect } from '@jest/globals';
import { COLORS, FUNNEL, HEALTH, withAlpha } from '@/design-system';
import { CATEGORICAL } from '../../../_constants/colors';
import { formatBRL } from '../../../_utils';
import {
  buildProfileHealthAriaLabel,
  buildProfileHealthChartData,
  buildProfileHealthLegendItems,
  buildProfileHealthTooltipRows,
  formatHealthMetricValue,
  HEALTH_STACK_BROKER_KEY,
  HEALTH_STACK_GAP_KEY,
  HEALTH_STACK_GAP_PX,
  HEALTH_STACK_METRICS,
  HEALTH_STACK_SCALE_MAX,
  HEALTH_STACK_TEAM_ALPHA,
  HEALTH_STACK_TEAM_KEY,
  HEALTH_STACK_ZERO_LINE_PX,
  isProfileHealthEmpty,
  resolveHealthStackFill,
  toHealthPxRatio,
  toHealthSegmentRatio,
} from '../profile-health-stacked';

const INNER_HEIGHT = 200;

const VALUES = {
  cad30d: 34,
  cad90d: 20,
  volume: 8.2,
  pctReceita: 18.4,
  conv: 40,
};

const TEAM_AVG = {
  cad30d: 20,
  cad90d: 25,
  volume: 4.4,
  pctReceita: 12.5,
  conv: 33,
};

describe('profile-health-stacked', () => {
  it('defines five categories with token colors and softer team / saturated broker fills', () => {
    expect(HEALTH_STACK_METRICS).toHaveLength(5);
    expect(HEALTH_STACK_METRICS.map((metric) => metric.key)).toEqual([
      'cad30d',
      'cad90d',
      'volume',
      'pctReceita',
      'conv',
    ]);
    expect(HEALTH_STACK_METRICS[0]).toMatchObject({
      short: 'Cad 30d',
      color: COLORS.brand,
      teamFill: withAlpha(COLORS.brand, HEALTH_STACK_TEAM_ALPHA),
      brokerFill: COLORS.brand,
    });
    expect(HEALTH_STACK_METRICS[1].color).toBe(COLORS.brandDeep);
    expect(HEALTH_STACK_METRICS[2].color).toBe(CATEGORICAL.teal);
    expect(HEALTH_STACK_METRICS[3].color).toBe(HEALTH.warningDeep);
    expect(HEALTH_STACK_METRICS[4].color).toBe(FUNNEL.completed);
  });

  it('pins each metric to a fixed scale max and clips values above the cap', () => {
    expect(HEALTH_STACK_SCALE_MAX).toEqual({
      cad30d: 30,
      cad90d: 80,
      volume: 20,
      pctReceita: 100,
      conv: 100,
    });
    expect(toHealthSegmentRatio(15, 30, INNER_HEIGHT)).toBe(0.5);
    expect(toHealthSegmentRatio(34, 30, INNER_HEIGHT)).toBe(1);
    expect(toHealthSegmentRatio(1000, 30, INNER_HEIGHT)).toBe(1);
    expect(toHealthSegmentRatio(18.4, 100, INNER_HEIGHT)).toBe(0.184);
  });

  it('turns a zero into a 2px ratio instead of collapsing the segment', () => {
    expect(toHealthSegmentRatio(0, 30, INNER_HEIGHT)).toBe(HEALTH_STACK_ZERO_LINE_PX / INNER_HEIGHT);
    expect(toHealthSegmentRatio(0, 100, INNER_HEIGHT)).toBe(0.01);
    expect(toHealthSegmentRatio(Number.NaN, 80, INNER_HEIGHT)).toBe(0.01);
    expect(toHealthPxRatio(HEALTH_STACK_GAP_PX, INNER_HEIGHT)).toBe(0.02);
    expect(toHealthSegmentRatio(0, 30, 0)).toBe(0);
  });

  it('builds stacked rows against the fixed scale, not max(broker, teamAvg)', () => {
    const rows = buildProfileHealthChartData(VALUES, TEAM_AVG, INNER_HEIGHT);
    const gapRatio = HEALTH_STACK_GAP_PX / INNER_HEIGHT;

    expect(rows).toHaveLength(5);
    expect(rows[0]).toEqual({
      name: 'Cad 30d',
      metricKey: 'cad30d',
      teamAvgValue: 20,
      brokerValue: 34,
      reference: 30,
      [HEALTH_STACK_TEAM_KEY]: 20 / 30,
      [HEALTH_STACK_GAP_KEY]: gapRatio,
      [HEALTH_STACK_BROKER_KEY]: 1,
    });
    expect(Object.keys(rows[0])).toEqual([
      'name',
      'metricKey',
      'teamAvgValue',
      'brokerValue',
      'reference',
      HEALTH_STACK_TEAM_KEY,
      HEALTH_STACK_GAP_KEY,
      HEALTH_STACK_BROKER_KEY,
    ]);
    expect(rows[2]).toMatchObject({
      name: 'Volume',
      metricKey: 'volume',
      teamAvgValue: 4.4,
      brokerValue: 8.2,
      reference: 20,
      [HEALTH_STACK_TEAM_KEY]: 4.4 / 20,
      [HEALTH_STACK_BROKER_KEY]: 8.2 / 20,
    });
    expect(rows[3]).toMatchObject({
      metricKey: 'pctReceita',
      reference: 100,
      [HEALTH_STACK_TEAM_KEY]: 12.5 / 100,
      [HEALTH_STACK_BROKER_KEY]: 18.4 / 100,
    });

    const inverted = buildProfileHealthChartData({ ...VALUES, cad30d: 10 }, { ...TEAM_AVG, cad30d: 20 }, INNER_HEIGHT);
    expect(inverted[0]).toMatchObject({
      reference: 30,
      [HEALTH_STACK_TEAM_KEY]: 20 / 30,
      [HEALTH_STACK_BROKER_KEY]: 10 / 30,
    });

    const zeroBroker = buildProfileHealthChartData({ ...VALUES, cad90d: 0 }, TEAM_AVG, INNER_HEIGHT);
    expect(zeroBroker[1]).toMatchObject({
      metricKey: 'cad90d',
      reference: 80,
      [HEALTH_STACK_TEAM_KEY]: 25 / 80,
      [HEALTH_STACK_BROKER_KEY]: HEALTH_STACK_ZERO_LINE_PX / INNER_HEIGHT,
      [HEALTH_STACK_GAP_KEY]: gapRatio,
    });
  });

  it('keeps the spacer gap out of tooltip, legend and aria copy', () => {
    const rows = buildProfileHealthChartData(VALUES, TEAM_AVG, INNER_HEIGHT);
    const tooltip = buildProfileHealthTooltipRows(rows[0]);
    const legend = buildProfileHealthLegendItems(VALUES, TEAM_AVG);
    const aria = buildProfileHealthAriaLabel(VALUES, TEAM_AVG);

    expect(rows[0][HEALTH_STACK_GAP_KEY]).toBe(HEALTH_STACK_GAP_PX / INNER_HEIGHT);
    expect(tooltip.map((row) => row.label)).toEqual(['Broker', 'Média da equipe']);
    expect(JSON.stringify(tooltip)).not.toContain(HEALTH_STACK_GAP_KEY);
    expect(legend.map((item) => item.key)).not.toContain(HEALTH_STACK_GAP_KEY);
    expect(aria).not.toContain(HEALTH_STACK_GAP_KEY);
  });

  it('resolves per-metric fills for the shared teamAvg/broker series', () => {
    const rows = buildProfileHealthChartData(VALUES, TEAM_AVG, INNER_HEIGHT);

    expect(resolveHealthStackFill(rows[0], HEALTH_STACK_TEAM_KEY)).toBe(
      withAlpha(COLORS.brand, HEALTH_STACK_TEAM_ALPHA),
    );
    expect(resolveHealthStackFill(rows[0], HEALTH_STACK_BROKER_KEY)).toBe(COLORS.brand);
    expect(resolveHealthStackFill(rows[2], HEALTH_STACK_BROKER_KEY)).toBe(CATEGORICAL.teal);
    expect(resolveHealthStackFill(rows[2], HEALTH_STACK_TEAM_KEY)).toBe(
      withAlpha(CATEGORICAL.teal, HEALTH_STACK_TEAM_ALPHA),
    );
    expect(resolveHealthStackFill({ metricKey: 'unknown' }, HEALTH_STACK_TEAM_KEY)).toBe(
      COLORS.brand,
    );
  });

  it('formats tooltip and legend with real units, not the scaled heights', () => {
    expect(formatHealthMetricValue('count', 34)).toBe('34');
    expect(formatHealthMetricValue('volume', 8.2)).toBe(formatBRL(8.2));
    expect(formatHealthMetricValue('percent', 18.4)).toBe('18%');

    expect(buildProfileHealthTooltipRows(buildProfileHealthChartData(VALUES, TEAM_AVG, INNER_HEIGHT)[0])).toEqual([
      { label: 'Broker', value: '34', color: expect.any(String) },
      { label: 'Média da equipe', value: '20', color: expect.any(String) },
    ]);
    expect(buildProfileHealthTooltipRows(buildProfileHealthChartData(VALUES, TEAM_AVG, INNER_HEIGHT)[2])).toEqual([
      { label: 'Broker', value: formatBRL(8.2), color: expect.any(String) },
      { label: 'Média da equipe', value: formatBRL(4.4), color: expect.any(String) },
    ]);

    const legend = buildProfileHealthLegendItems(VALUES, TEAM_AVG);
    expect(legend[0]).toMatchObject({ short: 'Cad 30d', value: '34', isAboveTeam: true });
    expect(legend[1]).toMatchObject({ short: 'Cad 90d', value: '20', isAboveTeam: false });
    expect(legend[2].value).toBe(formatBRL(8.2));
  });

  it('treats all-zero broker and team averages as empty', () => {
    const empty = {
      cad30d: 0,
      cad90d: 0,
      volume: 0,
      pctReceita: 0,
      conv: 0,
    };

    expect(isProfileHealthEmpty(empty, empty)).toBe(true);
    expect(isProfileHealthEmpty(VALUES, TEAM_AVG)).toBe(false);
    expect(isProfileHealthEmpty(VALUES, empty)).toBe(false);
    expect(buildProfileHealthAriaLabel(empty, empty)).toBe(
      'Perfil de saúde: sem dados para comparar com a equipe',
    );
    expect(buildProfileHealthAriaLabel(VALUES, TEAM_AVG)).toContain('Cad 30d 34 vs média 20');
    expect(buildProfileHealthAriaLabel(VALUES, TEAM_AVG)).toContain(`Volume ${formatBRL(8.2)}`);
  });
});

