'use client';

import { useMemo } from 'react';
import { ParentSize } from '@visx/responsive';
import { Bar } from '@/components/Charts/bar';
import { BarChart } from '@/components/Charts/bar-chart';
import { Grid } from '@/components/Charts/grid';
import { ChartTooltip } from '@/components/Charts/tooltip';
import { COLORS, FUNNEL } from '@/design-system';
import { cn } from '@/lib/utils';
import {
  GERENCIAL_PROFILE_LABEL_CLASS,
  GERENCIAL_PROFILE_TOPIC_CLASS,
} from '../../_constants/gerencial-ui';
import {
  buildProfileHealthAriaLabel,
  buildProfileHealthChartData,
  buildProfileHealthLegendItems,
  buildProfileHealthTooltipRows,
  HEALTH_STACK_BROKER_KEY,
  HEALTH_STACK_GAP_KEY,
  HEALTH_STACK_METRICS,
  HEALTH_STACK_TEAM_KEY,
  isProfileHealthEmpty,
  resolveHealthPlotInnerHeight,
  resolveHealthStackFill,
  type ProfileHealthValues,
} from './profile-health-stacked';

const CHART_MARGIN = { top: 16, right: 4, bottom: 10, left: 4 };
const CHART_MARGIN_Y = CHART_MARGIN.top + CHART_MARGIN.bottom;

export type ProfileHealthStackedChartProps = ProfileHealthValues & {
  teamAvg: ProfileHealthValues;
  className?: string;
};

export {
  buildProfileHealthAriaLabel,
  buildProfileHealthChartData,
  buildProfileHealthLegendItems,
  buildProfileHealthTooltipRows,
  formatHealthMetricValue,
  HEALTH_STACK_SCALE_MAX,
  isProfileHealthEmpty,
  toHealthSegmentRatio,
} from './profile-health-stacked';
export type { ProfileHealthValues } from './profile-health-stacked';

export function ProfileHealthStackedChart({
  cad30d,
  cad90d,
  volume,
  pctReceita,
  conv,
  teamAvg,
  className,
}: ProfileHealthStackedChartProps) {
  const values = useMemo(
    () => ({ cad30d, cad90d, volume, pctReceita, conv }),
    [cad30d, cad90d, volume, pctReceita, conv],
  );
  const isEmpty = useMemo(() => isProfileHealthEmpty(values, teamAvg), [values, teamAvg]);
  const legendItems = useMemo(
    () => buildProfileHealthLegendItems(values, teamAvg),
    [values, teamAvg],
  );
  const ariaLabel = useMemo(
    () => buildProfileHealthAriaLabel(values, teamAvg),
    [values, teamAvg],
  );

  return (
    <div className={cn('broker-profile-health', className)} data-testid="profile-health-stacked-chart">
      <section
        className="broker-profile-health-chart"
        aria-label={ariaLabel}
        data-ai-stat={ariaLabel}
      >
        {isEmpty ? (
          <p className="py-6 text-center font-satoshi text-xs italic" style={{ color: COLORS.textDim }}>
            Sem dados para comparar com a equipe
          </p>
        ) : (
          <div className="broker-profile-health-plot min-w-0 w-full overflow-hidden [&_svg]:overflow-hidden!">
            <ParentSize className="h-full min-h-0 w-full" debounceTime={10}>
              {({ width, height }) => {
                const innerHeight = resolveHealthPlotInnerHeight(height, CHART_MARGIN_Y);
                const data = buildProfileHealthChartData(values, teamAvg, innerHeight);

                return (
                  <div className="h-full min-w-0 w-full" style={{ width, height }}>
                    <BarChart
                      className="h-full min-w-0 w-full overflow-hidden"
                      data={data}
                      xDataKey="name"
                      stacked
                      stackGap={0}
                      valueMax={1}
                      aspectRatio="auto"
                      barGap={0.28}
                      margin={CHART_MARGIN}
                    >
                      <Grid horizontal stroke={COLORS.border} />
                      <Bar
                        dataKey={HEALTH_STACK_TEAM_KEY}
                        fill={(point) => resolveHealthStackFill(point, HEALTH_STACK_TEAM_KEY)}
                        stroke={COLORS.textDim}
                        lineCap="butt"
                      />
                      <Bar dataKey={HEALTH_STACK_GAP_KEY} fill="transparent" lineCap="butt" />
                      <Bar
                        dataKey={HEALTH_STACK_BROKER_KEY}
                        fill={(point) => resolveHealthStackFill(point, HEALTH_STACK_BROKER_KEY)}
                        stroke={COLORS.textDim}
                        lineCap="butt"
                      />
                      <ChartTooltip
                        showDatePill={false}
                        showDots={false}
                        detachPanel
                        rows={(point) => buildProfileHealthTooltipRows(point)}
                      />
                    </BarChart>
                  </div>
                );
              }}
            </ParentSize>
          </div>
        )}

        {!isEmpty && (
          <div className="mt-1 grid grid-cols-5 gap-1" aria-hidden>
            {HEALTH_STACK_METRICS.map((metric) => (
              <span
                key={metric.key}
                className={cn('min-w-0 truncate text-center', GERENCIAL_PROFILE_LABEL_CLASS)}
                style={{ color: COLORS.textDim }}
              >
                {metric.short}
              </span>
            ))}
          </div>
        )}
      </section>

      {!isEmpty && (
        <div className="broker-profile-health-list">
          <ul className="flex flex-col gap-4" aria-label="Tópicos de leitura do perfil de saúde">
            {legendItems.map((item) => (
              <li key={item.key} className="flex items-center gap-2">
                <span className="h-1.5 w-1.5 rounded-full" style={{ background: item.color }} />
                <span className={cn('flex-1', GERENCIAL_PROFILE_TOPIC_CLASS)} style={{ color: COLORS.textDim }}>
                  {item.short}
                </span>
                <span
                  className={cn('whitespace-nowrap tabular-nums', GERENCIAL_PROFILE_TOPIC_CLASS)}
                  style={{ color: item.color }}
                >
                  {item.value}
                </span>
                <span
                  className={GERENCIAL_PROFILE_TOPIC_CLASS}
                  style={{ color: item.isAboveTeam ? FUNNEL.completed : COLORS.danger }}
                >
                  <span aria-hidden>{item.isAboveTeam ? '▲' : '▼'}</span>
                  <span className="sr-only">
                    {item.isAboveTeam ? 'acima da média' : 'abaixo da média'}
                  </span>
                </span>
              </li>
            ))}
          </ul>
          <div className="mt-3 font-satoshi text-xs italic" style={{ color: COLORS.textDim }}>
            vs média da equipe
          </div>
        </div>
      )}
    </div>
  );
}
